package org.dromara.property.charge.receivable.service.impl;
import org.dromara.common.core.exception.ServiceException; import org.dromara.common.satoken.utils.LoginHelper; import org.dromara.property.charge.receivable.domain.Receivable; import org.dromara.property.charge.receivable.domain.bo.*; import org.dromara.property.charge.receivable.mapper.*; import org.dromara.property.project.mapper.ProjectMapper; import org.dromara.property.scope.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.List; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(org.mockito.junit.jupiter.MockitoExtension.class) class ReceivableServiceTest { @Mock ReceivableMapper mapper; @Mock ReceivableBatchMapper batchMapper; @Mock ProjectMapper projectMapper; @Mock PropertyProjectScopeService scope; ReceivableServiceImpl service; @BeforeEach void setUp(){service=new ReceivableServiceImpl(mapper,batchMapper,projectMapper,scope);}
 @Test void detailUsesPersistedProjectAndPreventsIdor(){Receivable r=row("UNPAID",bd("0"),LocalDate.now());r.setProjectId(202L);when(mapper.selectById(9L)).thenReturn(r);doThrow(new ServiceException("deny")).when(scope).assertBusinessAccess(202L,PropertyBusinessDomain.FINANCE,ProjectBusinessAction.READ);assertThrows(ServiceException.class,()->service.queryById(9L));}
 @Test void unpaidZeroCanBeCancelledAndKeepsAmounts(){Receivable r=row("UNPAID",bd("0"),LocalDate.now());when(mapper.selectActiveByIdForUpdate(9L)).thenReturn(r);when(mapper.updateById(any(Receivable.class))).thenReturn(1);try(MockedStatic<LoginHelper> login=mockStatic(LoginHelper.class)){login.when(LoginHelper::getUserId).thenReturn(88L);assertTrue(service.cancel(9L,cancel("录入错误")));}ArgumentCaptor<Receivable> c=ArgumentCaptor.forClass(Receivable.class);verify(mapper).updateById(c.capture());assertEquals("CANCELLED",c.getValue().getPaymentStatus());assertEquals(88L,c.getValue().getCancelledBy());assertNull(c.getValue().getReceivableAmount());}
 @Test void partialPaidAndCancelledAreRejected(){for(String status:List.of("PARTIAL","PAID","CANCELLED")){Receivable r=row(status,status.equals("CANCELLED")?bd("0"):bd("10"),LocalDate.now());when(mapper.selectActiveByIdForUpdate(9L)).thenReturn(r);assertThrows(ServiceException.class,()->service.cancel(9L,cancel("测试作废")));}verify(mapper,never()).updateById(any(Receivable.class));}
 @Test void missingWritePermissionRejectsCancellation(){Receivable r=row("UNPAID",bd("0"),LocalDate.now());when(mapper.selectActiveByIdForUpdate(9L)).thenReturn(r);doThrow(new ServiceException("deny")).when(scope).assertBusinessAccess(101L,PropertyBusinessDomain.FINANCE,ProjectBusinessAction.WRITE);assertThrows(ServiceException.class,()->service.cancel(9L,cancel("越权作废")));verify(mapper,never()).updateById(any(Receivable.class));}
 @Test void summaryExcludesCancelledAndCalculatesOverdueAtRuntime(){LocalDate yesterday=LocalDate.now().minusDays(1),today=LocalDate.now();when(mapper.selectList(any())).thenReturn(List.of(row("UNPAID",bd("0"),yesterday),row("PARTIAL",bd("40"),yesterday),row("PAID",bd("100"),yesterday),row("CANCELLED",bd("0"),yesterday),row("UNPAID",bd("0"),today)));ReceivableQueryBo q=new ReceivableQueryBo();q.setProjectId(101L);var s=service.summary(q);assertEquals(bd("400.00"),s.getReceivableTotal());assertEquals(bd("140.00"),s.getPaidTotal());assertEquals(bd("260.00"),s.getOutstandingTotal());assertEquals(bd("160.00"),s.getOverdueOutstandingTotal());}
 private Receivable row(String status,BigDecimal paid,LocalDate due){Receivable r=new Receivable();r.setId(9L);r.setProjectId(101L);r.setPaymentStatus(status);r.setReceivableAmount(bd("100"));r.setPaidAmount(paid);r.setDueDate(due);return r;} private ReceivableCancelBo cancel(String reason){ReceivableCancelBo b=new ReceivableCancelBo();b.setCancelReason(reason);return b;} private BigDecimal bd(String v){return new BigDecimal(v);}
}
